name: CI

on:
  push:
    branches: [main]
  pull_request:

permissions:
  contents: read

jobs:
  test:
    runs-on: ubuntu-latest
    # muni is mostly SQL, and the tests that matter most are the ones asking
    # whether a transaction across four tables leaves an account that works.
    # Those skip themselves without MUNI_TEST_DSN, which meant they never ran
    # anywhere but a laptop.
    services:
      postgres:
        image: postgres:16-alpine
        env:
          POSTGRES_PASSWORD: muni
          POSTGRES_DB: muni
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U postgres"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 10
    steps:
      - uses: actions/checkout@v7
      - name: Check the committed frontend placeholder
        run: scripts/check-webui-placeholder.sh
      - uses: actions/setup-go@v7
        with:
          go-version: '1.27.0'
          cache: true
      - uses: actions/setup-node@v7
        with:
          node-version: '22'
          cache: npm
          cache-dependency-path: frontend/package-lock.json
      - name: Frontend dependencies
        run: npm ci --no-audit --no-fund
        working-directory: frontend
      - name: Frontend typecheck and build
        run: npm run build
        working-directory: frontend
      - name: Frontend unit tests
        run: npm test
        working-directory: frontend
      # gofmt and vet are what every change to the Go side is run through by
      # hand before it is committed. A check that lives in someone's habit is
      # a check that is skipped the once it would have caught something.
      - name: Go formatting
        run: |
          unformatted=$(gofmt -l .)
          if [ -n "$unformatted" ]; then
            echo "gofmt -w 가 필요한 파일:"
            echo "$unformatted"
            exit 1
          fi
      - name: Go vet
        run: go vet ./...
      - name: Go tests
        run: go test ./...
        env:
          MUNI_TEST_DSN: postgres://postgres:muni@127.0.0.1:5432/muni?sslmode=disable
      - name: Build Linux binary
        run: CGO_ENABLED=0 go build -trimpath -o /tmp/muni ./cmd/muni

  image:
    runs-on: ubuntu-latest
    needs: test
    steps:
      - uses: actions/checkout@v7
      - uses: docker/setup-buildx-action@v4
      - uses: docker/build-push-action@v7
        with:
          context: .
          push: false
          tags: muni:v0.0.0-ci
          build-args: |
            VERSION=v0.0.0-ci
            COMMIT=${{ github.sha }}
            BUILD_TIME=ci
